import{_ as e,o,c as i,a1 as a}from"./chunks/framework.DdbKPUhY.js";const h=JSON.parse('{"title":"Documentation Style Spec","description":"","frontmatter":{},"headers":[],"relativePath":"spec/documentation-style.md","filePath":"spec/documentation-style.md"}'),r={name:"spec/documentation-style.md"};function n(s,t,u,l,c,q){return o(),i("div",null,[...t[0]||(t[0]=[a('<h1 id="documentation-style-spec" tabindex="-1">Documentation Style Spec <a class="header-anchor" href="#documentation-style-spec" aria-label="Permalink to &quot;Documentation Style Spec&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>This spec defines the writing standards for UVHTTP documentation and website content. All documentation must be written in a natural, professional tone free of AI-generated patterns.</p><h2 id="ai-flavor-—-prohibited-patterns" tabindex="-1">AI Flavor — Prohibited Patterns <a class="header-anchor" href="#ai-flavor-—-prohibited-patterns" aria-label="Permalink to &quot;AI Flavor — Prohibited Patterns&quot;">​</a></h2><p>The following patterns are considered &quot;AI flavor&quot; and must be removed from all documentation:</p><h3 id="universal-patterns-en-zh" tabindex="-1">Universal Patterns (EN + ZH) <a class="header-anchor" href="#universal-patterns-en-zh" aria-label="Permalink to &quot;Universal Patterns (EN + ZH)&quot;">​</a></h3><ul><li><strong>Hype adjectives</strong>: &quot;robust&quot;, &quot;seamless&quot;, &quot;cutting-edge&quot;, &quot;state-of-the-art&quot;, &quot;comprehensive&quot;, &quot;powerful&quot;, &quot;flexible&quot;, &quot;easy-to-use&quot;</li><li><strong>Empty intensifiers</strong>: &quot;very&quot;, &quot;extremely&quot;, &quot;highly&quot;, &quot;incredibly&quot;, &quot;remarkably&quot;</li><li><strong>Filler transitions</strong>: &quot;It&#39;s worth noting that&quot;, &quot;It&#39;s important to mention&quot;, &quot;In other words&quot;, &quot;Moreover&quot;, &quot;Furthermore&quot;, &quot;In addition&quot;</li><li><strong>Rhetorical questions</strong>: &quot;Why choose X?&quot;, &quot;What makes X different?&quot;</li><li><strong>Canned closings</strong>: &quot;Feel free to reach out&quot;, &quot;Happy coding!&quot;, &quot;Let me know&quot;</li><li><strong>Marketing claims</strong>: &quot;Setting the standard for&quot;, &quot;The most [adj] [noun] on the market&quot;</li></ul><h3 id="english-specific" tabindex="-1">English-Specific <a class="header-anchor" href="#english-specific" aria-label="Permalink to &quot;English-Specific&quot;">​</a></h3><ul><li><strong>Passive voice</strong>: &quot;can be used to&quot;, &quot;is designed to&quot;, &quot;is built to&quot;</li><li><strong>Nominalization</strong>: &quot;provides the ability to&quot;, &quot;offers support for&quot;</li><li><strong>Circumlocution</strong>: &quot;in the event that&quot; → &quot;if&quot;, &quot;for the purpose of&quot; → &quot;to&quot;</li></ul><h3 id="chinese-specific" tabindex="-1">Chinese-Specific <a class="header-anchor" href="#chinese-specific" aria-label="Permalink to &quot;Chinese-Specific&quot;">​</a></h3><ul><li><strong>Machine translation artifacts</strong>: &quot;的&quot; chains, unnatural word order</li><li><strong>Filler</strong>: &quot;值得一提的是&quot;, &quot;综上所述&quot;, &quot;首先&quot;, &quot;其次&quot;, &quot;最后&quot;</li><li><strong>Hype</strong>: &quot;高性能&quot;, &quot;卓越&quot;, &quot;全面&quot;, &quot;极致&quot;, &quot;高效&quot;, &quot;完善&quot;, &quot;简洁&quot;</li><li><strong>Emoji in technical docs</strong>: ❌/✅/⚡/📋/⚙️/📊/🎯/🔧/📈/🚀</li></ul><h2 id="target-voice" tabindex="-1">Target Voice <a class="header-anchor" href="#target-voice" aria-label="Permalink to &quot;Target Voice&quot;">​</a></h2><ul><li><strong>Terse</strong>: Say what it does, not what it&#39;s for</li><li><strong>Factual</strong>: Claims must be verifiable (test results, performance data)</li><li><strong>Concrete</strong>: Use specific numbers, not &quot;fast&quot; or &quot;efficient&quot;</li><li><strong>Active</strong>: &quot;The server handles requests&quot; not &quot;Requests are handled by the server&quot;</li></ul><h2 id="enforcement" tabindex="-1">Enforcement <a class="header-anchor" href="#enforcement" aria-label="Permalink to &quot;Enforcement&quot;">​</a></h2><p>The <code>de-ai-docs</code> skill (in the Claude Code skills directory) is used to scan and rewrite AI-sounding passages. It operates on:</p><ul><li>VitePress documentation pages (<code>.md</code>)</li><li>Website copy (<code>index.md</code>, feature cards)</li><li>API documentation</li><li>Chinese translations</li></ul><h2 id="quick-checklist" tabindex="-1">Quick Checklist <a class="header-anchor" href="#quick-checklist" aria-label="Permalink to &quot;Quick Checklist&quot;">​</a></h2><p>For each passage, ask:</p><ol><li>Would a human engineer write this naturally?</li><li>Can every claim be verified from code or test results?</li><li>Are there buzzwords that add no information?</li><li>Is the passive voice replaceable with active?</li><li>Would cutting 30% of the words improve clarity?</li></ol>',19)])])}const p=e(r,[["render",n]]);export{h as __pageData,p as default};
